import csv
from collections import defaultdict
from typing import Iterator

def read_rows(path: str) -> Iterator[dict]:
    # File iteration + csv.reader are both lazy: only a read buffer is resident
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            yield row

def parse_valid(rows: Iterator[dict]) -> Iterator[tuple[str, float]]:
    for row in rows:
        try:
            amount = float(row["amount"])
        except (KeyError, ValueError):
            continue  # skip malformed rows instead of crashing the stream
        if amount > 0 and row.get("region"):
            yield row["region"], amount

def total_by_region(path: str) -> dict[str, float]:
    totals: dict[str, float] = defaultdict(float)
    # Composed lazy pipeline: read_rows -> parse_valid, one item at a time
    for region, amount in parse_valid(read_rows(path)):
        totals[region] += amount  # accumulator bounded by #regions, not #rows
    return dict(totals)

if __name__ == "__main__":
    result = total_by_region("sales_30gb.csv")
    for region, total in sorted(result.items()):
        print(f"{region}: {total:,.2f}")

from dataclasses import dataclass
from itertools import islice
from typing import Iterator, Iterable

@dataclass(slots=True)  # slots=True drops the per-instance __dict__ -> less memory
class Event:
    user_id: int
    action: str
    ts: float

def read_events(path: str) -> Iterator[Event]:
    with open(path) as f:
        for line in f:
            uid, action, ts = line.rstrip("\n").split("\t")
            yield Event(int(uid), action, float(ts))

def batched(it: Iterable, n: int) -> Iterator[list]:
    it = iter(it)
    while True:
        batch = list(islice(it, n))  # pulls at most n items lazily
        if not batch:
            return
        yield batch

def bulk_load(path: str, batch_size: int = 10_000) -> int:
    total = 0
    for batch in batched(read_events(path), batch_size):
        # e.g. cursor.executemany(INSERT, [(e.user_id, e.action, e.ts) for e in batch])
        total += len(batch)
    return total

if __name__ == "__main__":
    print("loaded rows:", bulk_load("events_50gb.tsv", batch_size=10_000))
